function mockStudioExecutionSpec(modelType: string, mode: string) {
  const fluxModel = [
    'FluxSchnellPipeline',
    'FluxDevPipeline',
    'FluxKreaPipeline',
    'Flux2KleinPipeline',
    'FluxDepthPipeline',
    'FluxCannyPipeline',
    'FluxReduxPipeline',
    'FluxKontextPipeline',
  ] as const;
  const capability = fluxModel.includes(modelType as (typeof fluxModel)[number])
    ? mockFluxExecutionCapability(modelType as (typeof fluxModel)[number])
    : modelType === 'ZImageModularPipeline'
      ? mockZImageExecutionCapability()
      : modelType === 'QwenImageModularPipeline'
        ? mockQwenImageExecutionCapability()
        : modelType === 'MarigoldDepthPipeline'
          ? mockMarigoldDepthExecutionCapability()
          : modelType === 'HuggingFaceSpeechRecognitionModel'
            ? mockWhisperSpeechExecutionCapability()
            : modelType === 'FluxFillPipeline'
              ? mockFluxFillExecutionCapability()
              : modelType === 'QwenImageEditModularPipeline' && (mode === 'inpaint' || mode === 'outpaint')
                ? mockQwenEditInpaintExecutionCapability()
                : modelType === 'WanImageToVideoPipeline'
                  ? mockWanI2vExecutionCapability()
                  : modelType === 'WanTI2VPipeline'
                    ? mockWanTi2vExecutionCapability()
                    : modelType === 'WanVideoPipeline'
                      ? mockWanT2vExecutionCapability()
                      : modelType === 'WanVACEPipeline'
                        ? mockWanVaceT2vExecutionCapability()
                        : modelType === 'LTXVideoPipeline'
                          ? mockLtxT2vExecutionCapability()
                          : modelType === 'AceStepAudioPipeline'
                            ? mockAceTextToAudioExecutionCapability()
                            : null;
  return capability?.studioExecutionSpecs.find((item) => item.mode === mode);
}

function mockStudioExecutionSpecContract(modelType: string, mode: string) {
  const spec = mockStudioExecutionSpec(modelType, mode);
  return spec
    ? {
        schemaVersion: spec.schemaVersion,
        id: spec.id,
        contentHash: spec.contentHash,
        executionProfileId: spec.executionProfileId,
      }
    : undefined;
}

function mockAutoResourcePlan(form: Record<string, unknown> = {}) {
  const modelType = String(form.modelType ?? 'ZImageModularPipeline');
  const mode = String(form.mode ?? 'text_to_image');
  const executionProfileId = mockExecutionProfileIds[`${modelType}:${mode}`] ?? `mock:${modelType}:${mode}`;
  const spec = mockStudioExecutionSpec(modelType, mode);
  const selectedExecutionProfileId = spec?.executionProfileId ?? executionProfileId;
  if (!(modelType === 'QwenImageModularPipeline' && mode === 'text_to_image')) {
    const defaultRepos: Record<string, string> = {
      ZImageModularPipeline: 'Tongyi-MAI/Z-Image-Turbo',
      QwenImageEditModularPipeline: 'Qwen/Qwen-Image-Edit',
      QwenImageEditPlusModularPipeline: 'Qwen/Qwen-Image-Edit-2511',
      QwenImageLayeredModularPipeline: 'Qwen/Qwen-Image-Layered',
      WanVACEPipeline: 'Wan-AI/Wan2.1-VACE-1.3B-diffusers',
      WanVideoPipeline: 'Wan-AI/Wan2.1-T2V-1.3B-Diffusers',
      WanImageToVideoPipeline: 'Wan-AI/Wan2.2-I2V-A14B-Diffusers',
      WanTI2VPipeline: 'Wan-AI/Wan2.2-TI2V-5B-Diffusers',
      LTXVideoPipeline: 'Lightricks/LTX-Video-0.9.8-13B-distilled',
      AceStepAudioPipeline: 'ACE-Step/acestep-v15-xl-turbo-diffusers',
      MiniMaxMusic3ModularPipeline: 'MiniMaxAI/MiniMax-Music3',
      FluxSchnellPipeline: 'black-forest-labs/FLUX.1-schnell',
      FluxDevPipeline: 'black-forest-labs/FLUX.1-dev',
      FluxKreaPipeline: 'black-forest-labs/FLUX.1-Krea-dev',
      Flux2KleinPipeline: 'black-forest-labs/FLUX.2-klein-4B',
      FluxKontextPipeline: 'black-forest-labs/FLUX.1-Kontext-dev',
      FluxFillPipeline: 'black-forest-labs/FLUX.1-Fill-dev',
      FluxDepthPipeline: 'black-forest-labs/FLUX.1-Depth-dev',
      FluxCannyPipeline: 'black-forest-labs/FLUX.1-Canny-dev',
      FluxReduxPipeline: 'black-forest-labs/FLUX.1-Redux-dev',
      MarigoldDepthPipeline: 'prs-eth/marigold-depth-lcm-v1-0',
      HuggingFaceSpeechRecognitionModel: 'openai/whisper-tiny',
    };
    const defaultRepo = defaultRepos[modelType] ?? 'Tongyi-MAI/Z-Image-Turbo';
    const installed = mockInstalledRepos.has(defaultRepo);
    const modelDependencies =
      modelType === 'QwenImageModularPipeline' && mode === 'control_image'
        ? [
            {
              id: 'qwen-controlnet-union',
              kind: 'controlnet',
              repo: 'InstantX/Qwen-Image-ControlNet-Union',
              revision: 'b13036f066d6dee7c20513e263d3d673055e9de8',
            },
          ]
        : modelType === 'FluxReduxPipeline' && mode === 'edit_image'
          ? [
              {
                id: 'flux-redux-base',
                kind: 'base',
                repo: 'black-forest-labs/FLUX.1-dev',
                revision: '3de623fc3c33e44ffbe2bad470d0f45bccf2eb21',
              },
            ]
          : [];
    const directQwenEdit = modelType === 'QwenImageEditModularPipeline' && (mode === 'inpaint' || mode === 'outpaint');
    const executionPath =
      modelType === 'WanVACEPipeline'
        ? 'direct-wan-vace'
        : modelType === 'WanVideoPipeline' ||
            modelType === 'WanTI2VPipeline' ||
            modelType === 'WanImageToVideoPipeline' ||
            modelType === 'LTXVideoPipeline'
          ? 'direct-diffusers-video'
          : modelType === 'AceStepAudioPipeline'
            ? 'direct-diffusers-audio'
            : modelType.startsWith('Flux') || modelType === 'ZImageModularPipeline' || directQwenEdit
              ? 'direct-diffusers-image'
              : 'modular-diffusers';
    const loaderModule = executionPath.includes('audio')
      ? 'modules.DiffusersAudio'
      : executionPath.includes('wan') || executionPath.includes('video')
        ? 'modules.DiffusersVideo'
        : executionPath.includes('image')
          ? 'modules.DiffusersImage'
          : 'modules.ModularDiffusers';
    const candidateExecutionPath = spec?.executionPath ?? executionPath;
    const candidateLoaderModule = spec?.loaderModule ?? loaderModule;
    const candidateLoaderAction =
      spec?.loaderAction ?? (candidateLoaderModule === 'modules.ModularDiffusers' ? 'ModelsLoader' : 'LoadPipeline');
    const candidate = {
      id: `${modelType}-${mode}-declared-safe`,
      executionProfileId: selectedExecutionProfileId,
      modelType,
      mode,
      loaderModule: candidateLoaderModule,
      loaderAction: candidateLoaderAction,
      executionPath: candidateExecutionPath,
      pipelineClass:
        spec?.pipelineClass ??
        (modelType === 'WanVACEPipeline'
          ? 'WanVACEPipeline'
          : modelType === 'AceStepAudioPipeline'
            ? 'AceStepPipeline'
            : directQwenEdit
              ? 'QwenImageEditInpaintPipeline'
              : modelType === 'ZImageModularPipeline'
                ? 'ZImagePipeline'
                : modelType === 'FluxDepthPipeline' || modelType === 'FluxCannyPipeline'
                  ? 'FluxControlPipeline'
                  : modelType === 'FluxReduxPipeline'
                    ? 'FluxReduxPipeline'
                    : modelType === 'Flux2KleinPipeline'
                      ? 'Flux2KleinPipeline'
                      : modelType.startsWith('Flux')
                        ? 'FluxPipeline'
                        : modelType),
      modelDependencies,
      studioExecutionSpecContract: mockAdvertiseStudioExecutionSpecs
        ? mockStudioExecutionSpecContract(modelType, mode)
        : undefined,
      modelRepo: defaultRepo,
      resolvedArtifact: defaultRepo,
      artifact: defaultRepo,
      installTarget: {
        repo: defaultRepo,
        label: 'Auto model',
        reason: `Install ${defaultRepo} for Auto.`,
        actionLabel: 'Install Auto artifact',
      },
      dtype: 'bfloat16',
      quantizationMode: 'none',
      quantizedComponents: [],
      offloadMode: 'model_cpu',
      autoOffload: true,
      qualityTier: 'profile-default',
      generation: {
        width: Number(form.width ?? 1024),
        height: Number(form.height ?? 1024),
        steps: Number(form.steps ?? 30),
        guidanceScale: Number(form.guidanceScale ?? 4),
        negativePrompt: String(form.negativePrompt ?? ''),
        maxSequenceLength: Number(form.maxSequenceLength ?? 512),
      },
      installed,
      artifactStatus: { installed, complete: installed, reason: installed ? null : 'Artifact is not installed.' },
      requiresLocalProbe: false,
      proof: installed
        ? { status: mockReadyProofStatus, source: 'mock_profile' }
        : { status: 'unproven', source: 'mock_profile', message: 'Artifact is not installed.' },
    };
    return {
      error: false,
      schemaVersion: 2,
      resourceMode: 'auto',
      status: installed ? 'ready' : 'needs_setup',
      statusLabel: installed ? 'Ready with local Auto recipe' : 'Needs setup',
      blockingReason: installed ? null : 'No compatible local artifact was found for Auto.',
      compatibility: mockAutoCompatibility(installed),
      selectedCandidate: installed ? candidate : null,
      candidates: [candidate],
      hardware: { runtimeFingerprint: 'mock-runtime' },
      checkedAt: Date.now(),
    };
  }

  const qwenInstalled = mockInstalledRepos.has('unsloth/Qwen-Image-2512-unsloth-bnb-4bit');
  const selectedCandidate = {
    id: 'qwen-t2i-prequantized-model-cpu',
    executionProfileId,
    modelType,
    mode,
    loaderModule: 'modules.DiffusersImage',
    loaderAction: 'LoadPipeline',
    executionPath: 'direct-diffusers-image',
    pipelineClass: 'QwenImagePipeline',
    modelDependencies: [],
    studioExecutionSpecContract: mockAdvertiseStudioExecutionSpecs
      ? mockStudioExecutionSpecContract(modelType, mode)
      : undefined,
    modelRepo: 'unsloth/Qwen-Image-2512-unsloth-bnb-4bit',
    resolvedArtifact: 'unsloth/Qwen-Image-2512-unsloth-bnb-4bit',
    artifact: 'unsloth/Qwen-Image-2512-unsloth-bnb-4bit',
    installTarget: {
      repo: 'unsloth/Qwen-Image-2512-unsloth-bnb-4bit',
      label: 'Qwen Auto artifact',
      reason: 'Install unsloth/Qwen-Image-2512-unsloth-bnb-4bit for Qwen Auto.',
      actionLabel: 'Install quantized artifact',
    },
    dtype: 'bfloat16',
    quantizationMode: 'none',
    quantizedComponents: [],
    offloadMode: 'model_cpu',
    autoOffload: true,
    qualityTier: 'diffusers-compatible-prequantized-quality',
    generation: {
      width: 1024,
      height: 1024,
      steps: 50,
      guidanceScale: 4,
      negativePrompt: ' ',
      maxSequenceLength: 512,
    },
    installed: qwenInstalled,
    artifactStatus: {
      installed: qwenInstalled,
      complete: qwenInstalled,
      reason: qwenInstalled ? null : 'Artifact is not installed.',
    },
    requiresLocalProbe: false,
    proof: qwenInstalled
      ? { status: 'declared_safe', source: 'mock_requirements' }
      : { status: 'unproven', source: 'mock_requirements', message: 'Artifact is not installed.' },
  };
  return {
    error: false,
    schemaVersion: 2,
    resourceMode: 'auto',
    status: qwenInstalled ? 'ready' : 'needs_setup',
    statusLabel: qwenInstalled ? 'Ready with local Auto recipe' : 'Needs setup',
    blockingReason: qwenInstalled ? null : 'No compatible local artifact was found for Auto.',
    compatibility: mockAutoCompatibility(qwenInstalled),
    selectedCandidate: qwenInstalled ? selectedCandidate : null,
    candidates: [selectedCandidate],
    hardware: { runtimeFingerprint: 'mock-runtime' },
    requirementsMatched: qwenInstalled ? ['artifact', 'hardware', 'quality-defaults'] : [],
    requirementsMissing: qwenInstalled ? [] : ['Install unsloth/Qwen-Image-2512-unsloth-bnb-4bit for Qwen Auto.'],
    checkedAt: Date.now(),
  };
}

function mockHfCacheContains(cache: unknown[], repoId: string) {
  return cache.some((entry) => {
    if (typeof entry === 'string') return entry === repoId;
    if (!entry || typeof entry !== 'object') return false;
    return (entry as { id?: unknown }).id === repoId;
  });
}

