function waitForHttp(url: string, timeoutMs = 60_000) {
  return new Promise<void>((resolve, reject) => {
    const started = Date.now();
    const tick = () => {
      const req = http.get(url, (res) => {
        res.resume();
        if (res.statusCode && res.statusCode >= 200 && res.statusCode < 500) {
          resolve();
          return;
        }
        setTimeout(tick, 400);
      });
      req.on('error', () => {
        if (Date.now() - started > timeoutMs) {
          reject(new Error(`Timed out waiting for ${url}`));
          return;
        }
        setTimeout(tick, 400);
      });
    };
    tick();
  });
}

function isPortFree(port: number) {
  return new Promise<boolean>((resolve) => {
    const server = net.createServer();
    server.once('error', () => resolve(false));
    server.once('listening', () => server.close(() => resolve(true)));
    server.listen(port, '127.0.0.1');
  });
}

async function ensureFrontend() {
  if (!(await isPortFree(FRONTEND_PORT))) return;
  const command = process.platform === 'win32' ? 'cmd.exe' : 'npm';
  const args =
    process.platform === 'win32'
      ? ['/d', '/s', '/c', `npm.cmd run dev -- --host 127.0.0.1 --port ${FRONTEND_PORT}`]
      : ['run', 'dev', '--', '--host', '127.0.0.1', '--port', String(FRONTEND_PORT)];
  const child = spawn(command, args, {
    cwd: CLIENT_ROOT,
    env: {
      ...process.env,
      VITE_BACKEND_PROXY_TARGET: 'http://127.0.0.1:65530',
      MODIFF_VITE_CACHE_DIR: `node_modules/.vite-playwright-${FRONTEND_PORT}`,
      MODIFF_GALLERY_STABLE: '1',
    },
  });
  managedProcesses.push(child);
  await waitForHttp(FRONTEND_URL);
}

